1	export type Cell = [number, number];
2	
3	// --- Living population: how membership of the living set is decided ---
4	
5	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
6	  return x === otherX && y === otherY;
7	}
8	
9	function isLiving(cell: Cell, livingCells: Cell[]): boolean {
10	  return livingCells.some((other) => isSameCell(cell, other));
11	}
12	
13	// --- Neighbourhood topology: which cells are adjacent on the unbounded grid ---
14	
15	// A cell is not its own neighbour, so the zero offset is excluded and exactly
16	// the eight surrounding cells remain.
17	function isCellItself(dx: number, dy: number): boolean {
18	  return dx === 0 && dy === 0;
19	}
20	
21	function neighboursOf([x, y]: Cell): Cell[] {
22	  const offsets = [-1, 0, 1];
23	  return offsets.flatMap((dx) =>
24	    offsets
25	      .filter((dy) => !isCellItself(dx, dy))
26	      .map((dy): Cell => [x + dx, y + dy]),
27	  );
28	}
29	
30	function livingNeighbourCount(cell: Cell, livingCells: Cell[]): number {
31	  return neighboursOf(cell).filter((neighbour) =>
32	    isLiving(neighbour, livingCells),
33	  ).length;
34	}
35	
36	// --- Vitality policy: how a living neighbour count decides life ---
37	
38	const MIN_NEIGHBOURS_TO_SURVIVE = 2;
39	const MAX_NEIGHBOURS_TO_SURVIVE = 3;
40	
41	function survivesWith(livingNeighbours: number): boolean {
42	  return (
43	    livingNeighbours >= MIN_NEIGHBOURS_TO_SURVIVE &&
44	    livingNeighbours <= MAX_NEIGHBOURS_TO_SURVIVE
45	  );
46	}
47	
48	const NEIGHBOURS_TO_REPRODUCE = 3;
49	
50	function isBornWith(livingNeighbours: number): boolean {
51	  return livingNeighbours === NEIGHBOURS_TO_REPRODUCE;
52	}
53	
54	// --- Candidate enumeration and generation orchestration ---
55	
56	// Overlapping neighbourhoods name the same place more than once, and one place
57	// is one birth candidate, so only the first occurrence of each place is kept.
58	function distinctCells(cells: Cell[]): Cell[] {
59	  return cells.filter(
60	    (cell, index) =>
61	      cells.findIndex((other) => isSameCell(cell, other)) === index,
62	  );
63	}
64	
65	// Only dead cells touching a living cell can be born, so the infinite plane
66	// never has to be enumerated.
67	function deadNeighboursOf(livingCells: Cell[]): Cell[] {
68	  const deadNeighbours = livingCells
69	    .flatMap(neighboursOf)
70	    .filter((cell) => !isLiving(cell, livingCells));
71	  return distinctCells(deadNeighbours);
72	}
73	
74	function survivingCells(livingCells: Cell[]): Cell[] {
75	  return livingCells.filter((cell) =>
76	    survivesWith(livingNeighbourCount(cell, livingCells)),
77	  );
78	}
79	
80	function bornCells(livingCells: Cell[]): Cell[] {
81	  return deadNeighboursOf(livingCells).filter((cell) =>
82	    isBornWith(livingNeighbourCount(cell, livingCells)),
83	  );
84	}
85	
86	export function nextGeneration(livingCells: Cell[]): Cell[] {
87	  return [...survivingCells(livingCells), ...bornCells(livingCells)];
88	}
