// --- Candidate enumeration and generation orchestration ---

// Keeps only the first occurrence of each place.
function distinctCells(cells: Cell[]): Cell[] {
  return cells.filter(
    (cell, index) =>
      cells.findIndex((other) => isSameCell(cell, other)) === index,
  );
}

// Only dead cells touching a living cell can be born, so the infinite plane
// never has to be enumerated.
function deadNeighboursOf(livingCells: Cell[]): Cell[] {
  return livingCells
    .flatMap(neighboursOf)
    .filter((cell) => !isLiving(cell, livingCells));
}

// One place is one birth candidate, however many living neighbourhoods name it.
function birthCandidatesOf(livingCells: Cell[]): Cell[] {
  return distinctCells(deadNeighboursOf(livingCells));
}

function survivingCells(livingCells: Cell[]): Cell[] {
  return livingCells.filter((cell) =>
    survivesWith(livingNeighbourCount(cell, livingCells)),
  );
}

function bornCells(livingCells: Cell[]): Cell[] {
  return birthCandidatesOf(livingCells).filter((cell) =>
    isBornWith(livingNeighbourCount(cell, livingCells)),
  );
}

export function nextGeneration(livingCells: Cell[]): Cell[] {
  return [...survivingCells(livingCells), ...bornCells(livingCells)];
}
